package com.nexus.access.backend.accessibility;
import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.nexus.access.backend.exception.ResourceNotFoundException; import com.nexus.access.backend.user.*;
@Service @Transactional public class AccessibilityProfileService { private final AccessibilityProfileRepository profiles; private final UserRepository users; public AccessibilityProfileService(AccessibilityProfileRepository p,UserRepository u){profiles=p;users=u;} @Transactional(readOnly=true) public AccessibilityProfileResponseDTO get(UUID userId){return dto(find(userId));} public AccessibilityProfileResponseDTO update(UUID userId,UpdateAccessibilityProfileRequest r){AccessibilityProfile p=profiles.findByUserId(userId).orElseGet(()->{AccessibilityProfile x=new AccessibilityProfile();x.setUser(users.findById(userId).orElseThrow(()->new ResourceNotFoundException("User not found: "+userId)));return x;});apply(p,r);return dto(profiles.save(p));} private AccessibilityProfile find(UUID id){return profiles.findByUserId(id).orElseThrow(()->new ResourceNotFoundException("Accessibility profile not found for user: "+id));} private void apply(AccessibilityProfile p,UpdateAccessibilityProfileRequest r){p.setMobilityReduced(r.mobilityReduced());p.setWheelchair(r.wheelchair());p.setVisualImpairment(r.visualImpairment());p.setHearingImpairment(r.hearingImpairment());p.setCognitiveSupport(r.cognitiveSupport());p.setHighContrast(r.highContrast());p.setLargeText(r.largeText());p.setVoiceNavigation(r.voiceNavigation());p.setSimplifiedMode(r.simplifiedMode());} private AccessibilityProfileResponseDTO dto(AccessibilityProfile p){return new AccessibilityProfileResponseDTO(p.getId(),p.getUser().getId(),p.isMobilityReduced(),p.isWheelchair(),p.isVisualImpairment(),p.isHearingImpairment(),p.isCognitiveSupport(),p.isHighContrast(),p.isLargeText(),p.isVoiceNavigation(),p.isSimplifiedMode(),p.getCreatedAt(),p.getUpdatedAt());} }
